// Country and currency
const country = String($('When Executed by Another Workflow').first().json.country || '').trim().toUpperCase() === 'AE' ? 'AE' : 'IN';
const currency = country === 'AE' ? 'AED' : 'INR';
const product_a = $('When Executed by Another Workflow').first().json.product_a
const product_b = $('When Executed by Another Workflow').first().json.product_b

// Get Databricks responses
const rows_a = $('Execute a SQL query').all().map(item => item.json);
const rows_b = $('Execute a SQL query1').all().map(item => item.json);

// Pick matching product
function pick(rows, term) {
  rows = rows || [];
  const t = String(term || '').trim().toLowerCase();

  const exact = rows.filter(r =>
    r &&
    (
      String(r.sku || '').trim().toLowerCase() === t ||
      String(r.name || '').trim().toLowerCase() === t
    )
  );

  if (exact.length === 1) return exact[0];

  if (exact.length > 1) return null;

  if (rows.length === 1 && rows[0] && Object.keys(rows[0]).length > 0) {
    return rows[0];
  }

  return null;
}

const a = pick(rows_a, product_a);
const b = pick(rows_b, product_b);

// Default response
const empty = {
  found: false,
  ambiguous: false,
  message: '',
  currency: currency,
  product_a: '',
  product_b: '',
  price_a: 0,
  price_b: 0,
  price_difference: 0,
  cheaper: '',
  comparison_text: ''
};

// Check missing products
function isEmptyResponse(rows) {
  return rows.length === 0 ||
    rows.every(row => !row || Object.keys(row).length === 0);
}

if (isEmptyResponse(rows_a) || isEmptyResponse(rows_b)) {
  const missing = [];

  if (isEmptyResponse(rows_a)) {
    missing.push(String(product_a || ''));
  }

  if (isEmptyResponse(rows_b)) {
    missing.push(String(product_b || ''));
  }

  return [{
    json: {
      ...empty,
      message: `Could not find: ${missing.join(', ')}.`
    }
  }];
}

// Check ambiguous products
if (a === null || b === null) {

  const names = [];

  if (a === null) {
    names.push(`${product_a} could be: ${rows_a.map(r => r.name).join(', ')}`
    );
  }

  if (b === null) {
    names.push(
      `${product_b} could be: ${rows_b.map(r => r.name).join(', ')}`
    );
  }

  return [{
    json: {
      ...empty,
      found: true,
      ambiguous: true,
      message: `Be more specific. ${names.join('. ')}. Ask the customer which one.`
    }
  }];

}

// Calculate discounted prices
function price(r) {
  const base = country === 'AE'
    ? Number(r.price_aed || 0)
    : Number(r.price_inr || 0);

  const discount = Number(r.active_discount_percent || 0);

  return Math.round(base * (100 - discount) / 100);
}

const pa = price(a);
const pb = price(b);

const diff = Math.abs(pa - pb);

const cheaper = pa === pb
  ? 'same price'
  : pa < pb
    ? a.name
    : b.name;

// Comparison text
function line(label, va, vb) {
  return `${label}: ${va ?? 'N/A'} | ${vb ?? 'N/A'}`;
}

const text = [
  `${a.name} | ${b.name}`,
  line('Price', `${currency} ${pa}`, `${currency} ${pb}`),
  line('Movement', a.movement, b.movement),
  line('Material', a.material, b.material),
  line('Water resistance', `${parseInt(a.water_resistance_m) || 0} m`, `${parseInt(b.water_resistance_m) || 0} m`),
  line('Warranty', `${parseInt(a.warranty_months) || 0} months`, `${parseInt(b.warranty_months) || 0} months`),
  line('In stock', parseInt(a.stock) || 0, parseInt(b.stock) || 0)
].join('\n');

// Final response
return [{
  json: {
    found: true,
    ambiguous: false,
    message: 'OK',
    currency,
    product_a: a.name,
    product_b: b.name,
    price_a: pa,
    price_b: pb,
    price_difference: diff,
    cheaper,
    comparison_text: text
  }
}];

